// This node fetches cryptocurrency data for multiple symbols from the free CoinPaprika API.
// It does not require an API key.

// --- LOGIC ---

// Get the incoming item from the previous node.
// We expect an array of symbols, e.g., { "json": { "symbols": ["QUBIC", "BTC"] } }
const item = items[0];
const cryptoSymbols = item.json.symbols;

if (!cryptoSymbols || !Array.isArray(cryptoSymbols) || cryptoSymbols.length === 0) {
  throw new Error('No cryptocurrency symbols provided. Please provide an array of symbols in the "symbols" field.');
}

// --- Step 1: Fetch the entire coin list once to avoid multiple API calls ---
let allCoins;
try {
  console.log("Fetching the main coin list from CoinPaprika...");
  // FIX: Added 'json: true' to ensure the response is parsed as a JSON array.
  allCoins = await this.helpers.request({ uri: 'https://api.coinpaprika.com/v1/coins', json: true });
  console.log(`Found ${allCoins.length} coins.`);
} catch (error) {
  console.error("Error fetching coin list from CoinPaprika:", error.message);
  throw new Error('Could not connect to the CoinPaprika API to get the coin list.');
}

const allResults = [];

// --- Step 2: Loop through each symbol and get its data ---
for (const symbol of cryptoSymbols) {
  console.log(`Searching for symbol: ${symbol}`);

  // Find the specific coin that matches the user's symbol from the pre-fetched list
  const coinInfo = allCoins.find(c => c.symbol.toUpperCase() === symbol.toUpperCase());

  if (!coinInfo) {
    console.warn(`Could not find a coin with the symbol "${symbol}" on CoinPaprika. Skipping.`);
    continue; // Skip to the next symbol if not found
  }

  const coinId = coinInfo.id;
  console.log(`Found ID for ${symbol}: ${coinId}. Fetching ticker data...`);

  // Fetch the Ticker Data using the Coin ID
  let tickerData;
  try {
    // Also use json: true here for consistency
    tickerData = await this.helpers.request({ uri: `https://api.coinpaprika.com/v1/tickers/${coinId}`, json: true });
  } catch (error) {
    console.error(`Error fetching ticker data for ${coinId}:`, error.message);
    continue; // Skip if there's an error for this specific coin
  }

  // --- DATA PROCESSING ---
  const quote = tickerData.quotes.USD;
  const formattedData = {
    name: tickerData.name,
    symbol: tickerData.symbol,
    price: quote.price,
    price_formatted: `$${quote.price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 8 })}`,
    market_cap: quote.market_cap,
    market_cap_formatted: `$${Math.round(quote.market_cap).toLocaleString('en-US')}`,
    volume_24h: quote.volume_24h,
    percent_change_24h: quote.percent_change_24h,
    last_updated: tickerData.last_updated,
    paprika_url: `https://coinpaprika.com/coin/${coinId}/`
  };

  allResults.push(formattedData);
  console.log(`Successfully fetched and formatted data for ${symbol}.`);
}

// Replace the incoming data with a new object containing all our results
item.json.coin_data = allResults;

// Return the item to be used by the next node
return item;

"use strict";
/**
 * Minimal CoinPaprika fetcher for n8n AI Agent (free tier)
 * Endpoints used:
 *  - GET /v1/search?q=<SYMBOL>&c=currencies&limit=10
 *  - GET /v1/coins
 *  - GET /v1/tickers/{coin_id}?quotes=USD
 *  - (optional) GET /v1/global  when mode === "trending"
 *
 * Input (optional): query JSON string, e.g.
 * {"symbols":["BTC","QUBIC","XMR","ATOM","ETH"],"mode":"trending"}
 *
 * Output: { response: "<JSON string>" }
 */

const API = "https://api.coinpaprika.com/v1";

// -------- input parsing (n8n passes `query` as a string) ----------
let symbols = ["BTC", "QUBIC", "XMR", "ATOM", "ETH"];
let mode = "single";
try {
  if (typeof query === "string" && query.trim()) {
    const parsed = JSON.parse(query);
    if (Array.isArray(parsed.symbols) && parsed.symbols.length) symbols = parsed.symbols;
    if (parsed.mode) mode = String(parsed.mode);
  }
} catch { /* use defaults */ }

// -------- tiny helpers (sequential requests to be nice to free tier) ----------
async function fetchJSON(url) {
  const res = await fetch(url, { headers: { Accept: "application/json" } });
  if (!res.ok) throw new Error(`HTTP ${res.status} ${url}`);
  return res.json();
}

// Resolve a CoinPaprika coin_id for a ticker symbol (prefer /search; fallback /coins)
async function resolveCoinId(sym) {
  const up = sym.toUpperCase();

  // try /search first
  try {
    const s = await fetchJSON(`${API}/search?q=${encodeURIComponent(up)}&c=currencies&limit=10`);
    const exact = Array.isArray(s?.currencies)
      ? s.currencies.find(c => (c.symbol || "").toUpperCase() === up)
      : null;
    if (exact?.id) return exact.id;
  } catch { /* fall through */ }

  // fallback /coins
  const coins = await fetchJSON(`${API}/coins`);
  const match =
    coins.find(c => (c.symbol || "").toUpperCase() === up && c.is_active && c.type === "coin") ||
    coins.find(c => (c.symbol || "").toUpperCase() === up);
  return match?.id || null;
}

function fmtUSD(n) {
  if (typeof n !== "number" || !isFinite(n)) return null;
  return `$${n < 1 ? n.toFixed(8) : n.toFixed(2)}`;
}

// -------- main (sequential to avoid rate limits) ----------
async function main() {
  const out = { timestamp: new Date().toISOString(), coins: [] };

  for (const sym of symbols) {
    try {
      const id = await resolveCoinId(sym);
      if (!id) {
        out.coins.push({ symbol: sym, error: "Coin not found" });
        continue;
      }
      const t = await fetchJSON(`${API}/tickers/${id}?quotes=USD`);
      const usd = t?.quotes?.USD;

      const price = typeof usd?.price === "number" ? usd.price : null;
      const change24 = typeof usd?.percent_change_24h === "number" ? usd.percent_change_24h : null;

      out.coins.push({
        id,
        name: t?.name || sym,
        symbol: t?.symbol || sym,
        price,
        price_formatted: price !== null ? fmtUSD(price) : null,
        change_24h: change24,
        change_display: change24 !== null ? `${change24 >= 0 ? "⬆️" : "⬇️"} ${Math.abs(change24).toFixed(2)}%` : null,
        market_cap: usd?.market_cap ?? null,
        volume_24h: usd?.volume_24h ?? null,
        last_updated: t?.last_updated || null
      });
    } catch (e) {
      out.coins.push({ symbol: sym, error: String(e.message || e) });
    }
  }

  if (mode.toLowerCase() === "trending") {
    try {
      const g = await fetchJSON(`${API}/global`);
      out.global = {
        total_market_cap: g?.market_cap_usd ?? null,
        market_cap_change_24h: g?.market_cap_change_24h ?? null,
        bitcoin_dominance: g?.bitcoin_dominance_percentage ?? null
      };
    } catch (e) {
      out.global_error = String(e.message || e);
    }
  }

  // n8n requires response to be a STRING
  return { response: JSON.stringify(out) };
}

// -------- execute ----------
return main();

const isWebhookInput = $input.first().json.command === 'generate_news_video';
const prompt = $input.first().json.prompt;
const userId = $input.first().json.user_id;
const serverId = $input.first().json.server_id;
const userName = $input.first().json.user_name || 'User';
const newsType = $input.first().json.news_type || 'general';

const COMFYUI_SERVER = "127.0.0.1:8188";
const CLIENT_ID = `n8n_news_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const NEWS_ANCHOR_PATH = "C:/Users/Duck1/Desktop/DuckBot Parts/DuckBotAncor/DuckBotNewsAnchor1.png";

function processTradingFeeds(feedInputs) {
    const tradingNews = [];
    const marketData = {
        trending_coins: [],
        market_sentiment: 'neutral',
        key_events: [],
        price_movements: []
    };

    if (!feedInputs || feedInputs.length === 0) {
        return { trading_news: [], market_data: marketData, total_articles: 0 };
    }

    feedInputs.forEach(input => {
        if (input.json && Array.isArray(input.json)) {
            input.json.forEach(item => {
                const title = item.title || '';
                const description = item.description || '';
                const content = `${title} ${description}`.toLowerCase();

                const tradingKeywords = ['bitcoin', 'btc', 'ethereum', 'eth', 'crypto', 'trading', 'market', 'price'];
                const isTradingContent = tradingKeywords.some(keyword => content.includes(keyword));

                if (isTradingContent) {
                    tradingNews.push({
                        title: item.title,
                        description: item.description,
                        link: item.link,
                        pubDate: item.pubDate,
                        relevance: calculateRelevance(content)
                    });

                    if (content.includes('surge') || content.includes('bull') || content.includes('rally')) {
                        marketData.market_sentiment = 'bullish';
                    } else if (content.includes('dip') || content.includes('bear') || content.includes('crash')) {
                        marketData.market_sentiment = 'bearish';
                    }

                    const coinMentions = extractCoinMentions(content);
                    marketData.trending_coins.push(...coinMentions);
                }
            });
        }
    });

    marketData.trending_coins = [...new Set(marketData.trending_coins)];
    tradingNews.sort((a, b) => b.relevance - a.relevance);

    return {
        trading_news: tradingNews.slice(0, 5),
        market_data: marketData,
        total_articles: tradingNews.length,
        last_updated: new Date().toISOString()
    };
}

function calculateRelevance(content) {
    let score = 0;
    const highValueKeywords = ['bitcoin', 'ethereum', 'institutional', 'etf', 'regulation'];
    const mediumValueKeywords = ['crypto', 'trading', 'market', 'price'];

    highValueKeywords.forEach(keyword => {
        if (content.includes(keyword)) score += 3;
    });
    mediumValueKeywords.forEach(keyword => {
        if (content.includes(keyword)) score += 2;
    });

    return score;
}

function extractCoinMentions(content) {
    const coins = [];
    const coinPatterns = ['bitcoin', 'btc', 'ethereum', 'eth', 'solana', 'sol', 'cardano', 'ada'];

    coinPatterns.forEach(pattern => {
        if (content.includes(pattern)) {
            coins.push(pattern.toUpperCase());
        }
    });

    return coins;
}

function createNewsVideoWorkflow(enhancedPrompt, seed, newsAnchorPath) {
    return {
        "1": {
            "inputs": {
                "ckpt_name": "flux1-schnell-fp8.safetensors"
            },
            "class_type": "CheckpointLoaderSimple",
            "_meta": {"title": "Load Checkpoint"}
        },
        "2": {
            "inputs": {
                "text": enhancedPrompt,
                "clip": ["1", 1]
            },
            "class_type": "CLIPTextEncode", 
            "_meta": {"title": "CLIP Text Encode (Prompt)"}
        },
        "3": {
            "inputs": {
                "text": "text, watermark, low quality, blurry",
                "clip": ["1", 1]
            },
            "class_type": "CLIPTextEncode",
            "_meta": {"title": "CLIP Text Encode (Negative)"}
        },
        "4": {
            "inputs": {
                "width": 1920,
                "height": 1080,
                "batch_size": 1
            },
            "class_type": "EmptyLatentImage",
            "_meta": {"title": "Empty Latent Image"}
        },
        "5": {
            "inputs": {
                "seed": seed,
                "steps": 4,
                "cfg": 1.0,
                "sampler_name": "euler",
                "scheduler": "simple",
                "denoise": 1.0,
                "model": ["1", 0],
                "positive": ["2", 0],
                "negative": ["3", 0],
                "latent_image": ["4", 0]
            },
            "class_type": "KSampler",
            "_meta": {"title": "KSampler"}
        },
        "6": {
            "inputs": {
                "samples": ["5", 0],
                "vae": ["1", 2]
            },
            "class_type": "VAEDecode",
            "_meta": {"title": "VAE Decode"}
        },
        "7": {
            "inputs": {
                "image": newsAnchorPath,
                "upload": "image"
            },
            "class_type": "LoadImage",
            "_meta": {"title": "Load Purple Sunshine News Anchor"}
        },
        "8": {
            "inputs": {
                "image1": ["6", 0],
                "image2": ["7", 0],
                "blend_mode": "overlay",
                "opacity": 0.8
            },
            "class_type": "ImageBlend",
            "_meta": {"title": "Blend News Anchor"}
        },
        "9": {
            "inputs": {
                "filename_prefix": "TradingNewsVideo",
                "images": ["8", 0]
            },
            "class_type": "SaveImage",
            "_meta": {"title": "Save Trading News Image"}
        }
    };
}

function enhanceNewsPrompt(basePrompt, newsType, tradingData = null) {
    const newsStyles = {
        general: "professional news broadcast, clean studio lighting, newsroom background",
        breaking: "urgent news alert, dramatic lighting, red alert graphics",
        weather: "weather broadcast style, meteorological graphics",
        sports: "sports news studio, dynamic graphics",
        tech: "technology news, futuristic background",
        finance: "financial news studio, market graphics, trading charts background"
    };

    const newsStyle = newsStyles[newsType] || newsStyles.general;
    let enhancedPrompt = `${basePrompt}, ${newsStyle}, 4K resolution, professional broadcast quality, Purple Sunshine news anchor overlay`;

    if (tradingData && tradingData.market_data && (newsType === 'finance' || newsType === 'trading')) {
        const marketData = tradingData.market_data;
        if (marketData.market_sentiment !== 'neutral') {
            enhancedPrompt += `, market showing ${marketData.market_sentiment} trend`;
        }
        if (marketData.trending_coins.length > 0) {
            enhancedPrompt += `, featuring ${marketData.trending_coins.slice(0, 3).join(', ')} analysis`;
        }
    }

    return enhancedPrompt;
}

async function generateNewsVideo() {
    if (!isWebhookInput) {
        return { passthrough: true };
    }

    try {
        console.log(`📺 Starting news video generation: "${prompt}"`);

        const tradingInputs = $input.all().slice(1);
        const tradingData = processTradingFeeds(tradingInputs);

        const enhancedPrompt = enhanceNewsPrompt(prompt, newsType, tradingData);
        const seed = Math.floor(Math.random() * 2147483647);

        console.log(`🎯 Enhanced prompt: ${enhancedPrompt}`);
        console.log(`🎲 Using seed: ${seed}`);

        const workflow = createNewsVideoWorkflow(enhancedPrompt, seed, NEWS_ANCHOR_PATH);

        const payload = {
            prompt: workflow,
            client_id: CLIENT_ID
        };

        const response = await $http.request({
            method: 'POST',
            url: `http://${COMFYUI_SERVER}/prompt`,
            headers: {'Content-Type': 'application/json'},
            data: payload,
            timeout: 300000
        });

        if (response.status === 200 && response.data) {
            console.log(`✅ Successfully queued to ComfyUI`);

            return {
                success: true,
                prompt_id: response.data.prompt_id,
                enhanced_prompt: enhancedPrompt,
                seed: seed,
                news_type: newsType,
                user_id: userId,
                server_id: serverId,
                user_name: userName,
                original_prompt: prompt,
                trading_data: tradingData,
                news_anchor_used: NEWS_ANCHOR_PATH,
                timestamp: new Date().toISOString()
            };
        } else {
            throw new Error(`ComfyUI returned status ${response.status}`);
        }

    } catch (error) {
        console.error('❌ Error in news video generation:', error.message);
        return {
            success: false,
            error: error.message,
            user_id: userId,
            server_id: serverId
        };
    }
}

if (isWebhookInput) {
    return await generateNewsVideo();
} else {
    return $input.first().json;
}

const input = $input.first().json;
const isNewsVideoResponse = input.success !== undefined && input.prompt_id;

if (isNewsVideoResponse) {
    const embed = {
        title: input.success ? "📺 Trading News Video Generated!" : "❌ Generation Failed",
        description: input.success ? 
            `**Content:** ${input.original_prompt}\n**Type:** ${input.news_type}\n🎭 **Purple Sunshine anchor applied**` :
            `**Error:** ${input.error}`,
        color: input.success ? 0x00ff00 : 0xff0000,
        fields: [],
        timestamp: new Date().toISOString(),
        footer: { text: "DuckBot v2.3.0 - Trading Video Enhanced" }
    };

    if (input.success) {
        embed.fields.push(
            { name: "🎲 Seed", value: input.seed.toString(), inline: true },
            { name: "📊 Trading Data", value: input.trading_data ? "Integrated" : "None", inline: true },
            { name: "🔗 Prompt ID", value: input.prompt_id, inline: true }
        );

        if (input.trading_data && input.trading_data.market_data) {
            const marketData = input.trading_data.market_data;
            if (marketData.market_sentiment !== 'neutral') {
                embed.fields.push({
                    name: "📈 Market Sentiment",
                    value: marketData.market_sentiment.toUpperCase(),
                    inline: true
                });
            }
        }
    }

    return {
        discord_response: { embeds: [embed] },
        success: input.success,
        webhook_response: true
    };
} else {
    return input;
}

// Get the incoming item from the previous node (the Webhook).
// 'items' is an array of all incoming items, and we usually work with the first one.
const item = items[0];

// This code generates a unique ID without needing any special libraries.
// It combines the current timestamp with a random string.
const sessionId = Date.now().toString(36) + Math.random().toString(36).substring(2);

// Add the new 'sessionId' field to the 'json' object of the incoming item.
// This preserves all the original data from the webhook.
item.json.sessionId = sessionId;

// Return the modified item.
// Now the output will contain both the original webhook data and the new session ID.
return item;

